coachView.changeJsFunction:
// MultiCheckbox - Change Event Handler
// Executed when the widget data changes
var _this = this;

// Get the updated data
var data = _this.getData();

console.log('MultiCheckbox data changed:', data);

// Re-render the checkboxes to reflect the new selection state
var container = _this.context.element.querySelector(".multicheckbox-container");
var optionsContainer = container.querySelector(".multicheckbox-options");

// Update checkbox states based on new data
var checkboxes = optionsContainer.querySelectorAll(".multicheckbox-input");
var selectedValues = data || [];

if (!Array.isArray(selectedValues)) {
  selectedValues = [];
}

checkboxes.forEach(function(checkbox) {
  var isSelected = selectedValues.indexOf(checkbox.value) !== -1;
  checkbox.checked = isSelected;
});

// Update ARIA label
var count = selectedValues.length;
var label = count === 0 ? "No items selected" :
            count === 1 ? "1 item selected" :
            count + " items selected";
container.setAttribute("aria-label", label);

// Made with Bob

inlineScript.scriptBlock:
// Store widget context reference
var widget = this;

// Get DOM elements
var container = widget.context.element.querySelector(".multicheckbox-container");
var labelElement = container.querySelector(".multicheckbox-label");
var selectAllWrapper = container.querySelector(".multicheckbox-select-all-wrapper");
var selectAllInput = container.querySelector(".multicheckbox-select-all-input");
var optionsContainer = container.querySelector(".multicheckbox-options");
var helperText = container.querySelector(".multicheckbox-helper-text");

// Get configuration options
var options = widget.getOption("options");
var label = widget.getOption("label") || "";
var layout = widget.getOption("layout") || "vertical";
var showSelectAll = widget.getOption("showSelectAll");
var disabled = widget.getOption("disabled");
var helperTextValue = widget.getOption("helperText") || "";

// Validate and ensure options is an array with .items property
if (options && options.items && Array.isArray(options.items)) {
  options = options.items;
} else if (!options || !Array.isArray(options)) {
  options = [];
}

// Set default values
if (showSelectAll === undefined || showSelectAll === null) showSelectAll = true;
if (disabled === undefined || disabled === null) disabled = false;

// Get selected values from bound data
var selectedValues = widget.getData() || [];
if (!Array.isArray(selectedValues)) {
  selectedValues = [];
}

// State management
var state = {
  selectedValues: selectedValues,
  allOptions: options.slice() // Create a copy
};

// Initialize widget
function init() {
  // Set label
  if (label) {
    labelElement.textContent = label;
  }

  // Set helper text
  if (helperTextValue) {
    helperText.textContent = helperTextValue;
  }

  // Show/hide Select All
  if (!showSelectAll) {
    selectAllWrapper.style.display = "none";
  }

  // Set layout
  if (layout === "horizontal") {
    container.classList.add("horizontal");
  } else if (layout === "compact") {
    container.classList.add("compact");
  }

  // Set disabled state
  if (disabled) {
    container.classList.add("disabled");
    if (selectAllInput) selectAllInput.disabled = true;
  }

  // Attach Select All event listener
  if (showSelectAll && selectAllInput) {
    selectAllInput.addEventListener("change", handleSelectAllChange);
  }

  // Render checkboxes
  renderCheckboxes();
  updateSelectAllState();
}

// Render checkboxes
function renderCheckboxes() {
  optionsContainer.innerHTML = "";

  if (state.allOptions.length === 0) {
    var noOptions = document.createElement("div");
    noOptions.className = "multicheckbox-no-options";
    noOptions.textContent = "No options available";
    optionsContainer.appendChild(noOptions);
    return;
  }

  state.allOptions.forEach(function(option, index) {
    var optionEl = document.createElement("label");
    optionEl.className = "multicheckbox-option";
    optionEl.setAttribute("role", "listitem");

    if (disabled) {
      optionEl.classList.add("disabled");
    }

    // Hidden checkbox input
    var input = document.createElement("input");
    input.type = "checkbox";
    input.className = "multicheckbox-input";
    input.value = option.value;
    input.id = "multicheckbox-" + widget.context.viewid + "-" + index;

    var isSelected = state.selectedValues.indexOf(option.value) !== -1;
    if (isSelected) {
      input.checked = true;
    }

    if (disabled) {
      input.disabled = true;
    }

    // Custom checkbox
    var checkbox = document.createElement("span");
    checkbox.className = "multicheckbox-checkbox";
    checkbox.setAttribute("aria-hidden", "true");
    checkbox.innerHTML = '<svg viewBox="0 0 16 16" fill="currentColor"><path d="M6.5 11.7L3.3 8.5l.7-.7 2.5 2.5 5.2-5.2.7.7z"/></svg>';

    // Label text
    var labelText = document.createElement("span");
    labelText.className = "multicheckbox-label-text";
    labelText.textContent = option.name;
    labelText.setAttribute("for", input.id);

    // Assemble option
    optionEl.appendChild(input);
    optionEl.appendChild(checkbox);
    optionEl.appendChild(labelText);

    // Change handler
    input.addEventListener("change", function(e) {
      handleCheckboxChange(option.value, e.target.checked);
    });

    optionsContainer.appendChild(optionEl);
  });
}

// Handle checkbox change
function handleCheckboxChange(value, checked) {
  if (disabled) return;

  var index = state.selectedValues.indexOf(value);

  if (checked && index === -1) {
    // Add to selected values
    state.selectedValues.push(value);
  } else if (!checked && index !== -1) {
    // Remove from selected values
    state.selectedValues.splice(index, 1);
  }

  // Update data binding
  widget.setData(state.selectedValues);

  // Update Select All state
  updateSelectAllState();

  // Update ARIA label
  updateAriaLabel();
}

// Handle Select All change
function handleSelectAllChange(e) {
  if (disabled) return;

  // Clear indeterminate state first
  if (selectAllInput) {
    selectAllInput.indeterminate = false;
  }

  var checked = e.target.checked;

  if (checked) {
    // Select all options
    state.selectedValues = state.allOptions.map(function(opt) {
      return opt.value;
    });
  } else {
    // Deselect all options
    state.selectedValues = [];
  }

  // Update data binding - check if binding exists first
  try {
    if (widget && widget.context && widget.context.binding) {
      widget.setData(state.selectedValues);
    }
  } catch (error) {
    console.log('MultiCheckbox: Unable to update data binding', error);
  }

  // Update all checkboxes to match
  var checkboxes = optionsContainer.querySelectorAll(".multicheckbox-input");
  checkboxes.forEach(function(checkbox) {
    checkbox.checked = checked;
  });

  // Update ARIA label
  updateAriaLabel();
}

// Update Select All checkbox state
function updateSelectAllState() {
  if (!showSelectAll || !selectAllInput) return;

  var allSelected = state.selectedValues.length === state.allOptions.length && state.allOptions.length > 0;
  var someSelected = state.selectedValues.length > 0 && state.selectedValues.length < state.allOptions.length;

  selectAllInput.checked = allSelected;
  selectAllInput.indeterminate = someSelected;
}

// Update ARIA label
function updateAriaLabel() {
  var count = state.selectedValues.length;
  var label = count === 0 ? "No items selected" :
              count === 1 ? "1 item selected" :
              count + " items selected";
  container.setAttribute("aria-label", label);
}

// Initialize the widget
init();
updateAriaLabel();

// Made with Bob

/* MultiCheckbox Widget - Carbon Design System */
/* Colors and typography aligned with themes/Carbon.less */

.multicheckbox-container {
  width: 100%;
  font-family: 'IBM Plex Sans', 'Helvetica Neue', Arial, sans-serif; /* @bpm-font-family-sans-serif */
  font-size: 14px; /* @bpm-font-size-base */
  color: #161616; /* @bpm-text-color */
}

/* Label */
.multicheckbox-label-wrapper {
  margin-bottom: 8px;
}

.multicheckbox-label {
  display: block;
  font-size: 12px; /* @bpm-font-size-small */
  font-weight: 400; /* @bpm-font-weight-normal */
  line-height: 1.33;
  color: #525252; /* Gray 70 */
  letter-spacing: 0.32px;
}

.multicheckbox-label:empty {
  display: none;
}

/* Select All Wrapper */
.multicheckbox-select-all-wrapper {
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid #e0e0e0; /* Gray 20 */
}

.multicheckbox-select-all-wrapper:empty {
  display: none;
}

.multicheckbox-select-all-option {
  font-weight: 600; /* @bpm-font-weight-semibold */
}

.multicheckbox-select-all-text {
  color: #0f62fe; /* @bpm-color-primary */
}

/* Options Container */
.multicheckbox-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Checkbox Option Item */
.multicheckbox-option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  cursor: pointer;
  position: relative;
  transition: background-color 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multicheckbox-option:hover {
  background-color: #f4f4f4; /* Gray 10 */
}

.multicheckbox-option:focus-within {
  outline: 2px solid #0f62fe; /* @bpm-color-primary */
  outline-offset: 2px;
}

/* Checkbox Input (Hidden) */
.multicheckbox-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom Checkbox */
.multicheckbox-checkbox {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 1px solid #8d8d8d; /* Gray 50 */
  background-color: transparent;
  transition: all 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
  flex-shrink: 0;
  position: relative;
}

.multicheckbox-option:hover .multicheckbox-checkbox {
  border-color: #0f62fe; /* @bpm-color-primary */
}

.multicheckbox-input:checked + .multicheckbox-checkbox {
  background-color: #0f62fe; /* @bpm-color-primary */
  border-color: #0f62fe; /* @bpm-color-primary */
}

.multicheckbox-input:focus + .multicheckbox-checkbox {
  outline: 2px solid #0f62fe; /* @bpm-color-primary */
  outline-offset: 2px;
}

/* Checkmark Icon */
.multicheckbox-checkbox svg {
  width: 12px;
  height: 12px;
  color: #ffffff; /* @bpm-body-bg */
  opacity: 0;
  transform: scale(0.5);
  transition: all 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.multicheckbox-input:checked + .multicheckbox-checkbox svg {
  opacity: 1;
  transform: scale(1);
}

/* Label Text */
.multicheckbox-label-text {
  flex: 1;
  font-size: 14px; /* @bpm-font-size-base */
  line-height: 1.29;
  color: #161616; /* @bpm-text-color */
  user-select: none;
}

/* Helper Text */
.multicheckbox-helper-text {
  margin-top: 8px;
  font-size: 12px; /* @bpm-font-size-small */
  line-height: 1.33;
  color: #525252; /* Gray 70 */
}

.multicheckbox-helper-text:empty {
  display: none;
}

.multicheckbox-helper-text.error {
  color: #da1e28; /* @bpm-color-alert */
}

/* Error State */
.multicheckbox-container.error .multicheckbox-checkbox {
  border-color: #da1e28; /* @bpm-color-alert */
}

.multicheckbox-container.error .multicheckbox-input:checked + .multicheckbox-checkbox {
  background-color: #da1e28; /* @bpm-color-alert */
  border-color: #da1e28; /* @bpm-color-alert */
}

/* Disabled State */
.multicheckbox-option.disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.multicheckbox-option.disabled:hover {
  background-color: transparent;
}

.multicheckbox-option.disabled .multicheckbox-checkbox {
  border-color: #c6c6c6; /* Gray 30 - @bpm-link-text-color-disabled */
  background-color: #f4f4f4; /* Gray 10 */
}

.multicheckbox-option.disabled .multicheckbox-input:checked + .multicheckbox-checkbox {
  background-color: #c6c6c6; /* Gray 30 - @bpm-link-text-color-disabled */
  border-color: #c6c6c6; /* Gray 30 - @bpm-link-text-color-disabled */
}

.multicheckbox-option.disabled .multicheckbox-label-text {
  color: #c6c6c6; /* Gray 30 - @bpm-link-text-color-disabled */
}

/* Horizontal Layout */
.multicheckbox-container.horizontal .multicheckbox-options {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 16px;
}

.multicheckbox-container.horizontal .multicheckbox-option {
  padding: 8px 12px;
}

/* Compact Layout */
.multicheckbox-container.compact .multicheckbox-option {
  padding: 4px 0;
  gap: 6px;
}

.multicheckbox-container.compact .multicheckbox-options {
  gap: 4px;
}

/* Responsive Design */
@media (max-width: 672px) {
  .multicheckbox-container.horizontal .multicheckbox-options {
    flex-direction: column;
    gap: 8px;
  }

  .multicheckbox-option {
    padding: 10px 0;
  }
}

/* Accessibility - High Contrast Mode */
@media (prefers-contrast: high) {
  .multicheckbox-checkbox {
    border-width: 2px;
  }

  .multicheckbox-input:focus + .multicheckbox-checkbox {
    outline-width: 3px;
  }
}

/* Animation */
@keyframes checkboxCheck {
  0% {
    opacity: 0;
    transform: scale(0.5) rotate(-45deg);
  }
  50% {
    transform: scale(1.1) rotate(0deg);
  }
  100% {
    opacity: 1;
    transform: scale(1) rotate(0deg);
  }
}

.multicheckbox-input:checked + .multicheckbox-checkbox svg {
  animation: checkboxCheck 0.2s ease-out;
}

/* Made with Bob */
